#include <stdio.h>

int main(void)
{
    struct Node { int value; struct Node *prev; };
    struct Node a = {12, NULL};
    struct Node b = {24, &a};
    printf("%d\n", b.prev->value);
    return 0;
}

#include <stdio.h>

int main(void)
{
    struct Node { int value; struct Node *prev; struct Node *next; };
    struct Node a = {12, NULL, NULL};
    struct Node b = {24, &a, NULL};
    struct Node c = {36, &b, NULL};
    a.next = &b;
    b.next = &c;
    a.next = &c;
    c.prev = &a;
    printf("%d\n", c.prev->value);
    return 0;
}

